    default: "move",
    description: "Focus",
  },
  magnify: {
    type: "number",
    default: 1.1,
    min: 1,
    max: 1.5,
    step: 0.01,
    description: "Magnify",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Instrument Sans",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
