  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","focus","magnify","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  focus: "move",
  magnify: 1.1,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type GlassCapsuleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GlassCapsuleBase>;

const GlassCapsuleInner = forwardRef<
  HTMLDivElement,
  GlassCapsuleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GlassCapsule>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GlassCapsuleBase
          {...(componentProps as unknown as ComponentProps<typeof GlassCapsuleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GlassCapsule = Interactive.withSchema({
  Component: GlassCapsuleInner,
  componentName: "<GlassCapsule>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
